import json, numpy as np
x=np.load('x2.npy'); names=['XL','mp','mq','kiv','kpv','TPf','TQf','TVf']
params={n:float(v) for n,v in zip(names,x)}
params.update({'w0':2*np.pi*60,'Emax':1.2})
sub={
 "params":params,
 "defs":{
   "E0":"sqrt((V0+Q0*XL/V0)**2+(P0*XL/V0)**2)",
   "Vcmd":"Vset+mq*(Q0-Vq)",
   "Vq":"Qm",
   "E":"min(max(kpv*(Vcmd-Vm)+xv,0),Emax)",
   "dP":"V*E*sin(dl-theta)/XL",
   "dQ":"V*(E*cos(dl-theta)-V)/XL"
 },
 "states":{
   "Pm":{"rhs":"(P-Pm)/TPf","init":"P0"},
   "Qm":{"rhs":"(Q-Qm)/TQf","init":"Q0"},
   "Vm":{"rhs":"(V-Vm)/TVf","init":"V0"},
   "dl":{"rhs":"w0*mp*(P0-Pm)","init":"theta0+atan2(P0*XL/V0, V0+Q0*XL/V0)"},
   "xv":{"rhs":"kiv*(Vcmd-Vm)","init":"E0"}
 },
 "outputs":{"P":"dP","Q":"dQ"}
}
